  const money = (bn) => Math.abs(bn) >= 1000 ? "$" + (bn / 1000).toFixed(2) + "tn" : "$" + Math.round(bn) + "bn";
  const LAGF = { "30d": 0.12, "6m": 0.55, "1y": 0.95, "3y": 1 }; // capex realisation (same as 'slow' lag)
  const kpis = [
    { label: "Capex not spent", tag: "model", fn: (c) => c.cut * c.b("capex12m") * LAGF[c.horizon], format: money, severity: (v, c) => c.cut,
      sub: (c) => "of " + money(c.b("capex12m")) + " planned over 12 months", how: "Cut × planned 12-month capex (Big 4 guidance midpoints + Oracle + CoreWeave + Nebius), times how much of that spending would normally land by this horizon.", src: [s.googQ, s.amznQ, s.metaQ, s.msftBond, s.orclBean, s.nbis] },
    { label: "AI venture funding lost", tag: "model", fn: (c) => c.cut * c.b("aiVC12m") * (c.horizon === "30d" ? 0.15 : c.horizon === "6m" ? 0.55 : 1), format: money, severity: (v, c) => c.cut,
      sub: () => "Q3 2026 pace: $102bn a quarter", how: "Cut × annualised AI venture funding at the Q3 2026 pace, phased in over the year.", src: [s.cbVC] },
    { label: "NVIDIA data-center revenue at risk", tag: "model", fn: (c) => c.h("nvidia") * c.b("nvdaDC12m"), format: money, severity: (v, c) => c.h("nvidia"),
      sub: (c) => Math.round(c.h("nvidia") * 100) + "% of a $356bn annual pace", how: "NVIDIA stress × last quarter's Data Center revenue ($89.0bn) × 4.", src: [s.nvdaQ] },
    { label: "Cloud backlog under stress", tag: "model", fn: (c) => Object.entries(c.b("backlogs")).reduce((a, [id, v]) => a + v * c.h(id), 0), format: money, severity: (v) => Math.min(1, v / 1300),
      sub: () => "of $2.62tn signed backlogs", how: "Each cloud's backlog × its stress: Microsoft $677bn, Oracle $664bn, AWS $578bn, Google $561bn, CoreWeave $104bn, Nebius $40bn.", src: [s.msftQ, s.orclQ, s.amzn10q, s.googCall, s.crwvQ, s.nbis] },
    { label: "Lab compute commitments at risk", tag: "model", fn: (c) => c.b("labCommit") * (c.h("openai") * 0.606 + c.h("anthropic") * 0.394), format: money, severity: (v) => Math.min(1, v / 600),
      sub: () => "OpenAI ≈ $600bn + Anthropic ≈ $390bn", how: "OpenAI's planned compute spend through 2030 × OpenAI stress, plus Anthropic's S-1 named commitments × Anthropic stress.", src: [s.oai600, s.antS1] },
    { label: "Private credit under stress", tag: "model", fn: (c) => c.b("privateCredit") * c.h("credit"), format: money, severity: (v, c) => c.h("credit"),
      sub: () => "of ≈ $700bn expected into data centers 2026–28", how: "Credit-node stress × Morgan Stanley's estimate of private credit going into data-center capex 2026–28 (cited by the Bank of England).", src: [s.boe, s.msGap] },
    { label: "Stock-market value at risk", tag: "model", fn: (c) => c.mcapLoss, format: money, severity: (v) => Math.min(1, v / 12000),
      sub: () => "listed companies on the map, Oct 30 prices", how: "For every listed company on the map: market value × stress × 0.8 (assumption: stress 100 ≈ an 80% fall, like Cisco and the Nasdaq in 2000–02).", src: [s.yahoo, s.ciscoCap, s.nasdaq] },
    { label: "US GDP growth hit", tag: "model", fn: (c) => { const direct = c.cut * (c.b("aiGrowthPP") * 0.5 + c.b("aiGrowthPPNet") * 0.5) * LAGF[c.horizon]; const wealth = c.mcapLoss * c.b("wealthMPC") / c.b("usGDP") * 100 * (c.horizon === "30d" ? 0.2 : c.horizon === "6m" ? 0.6 : 1) * (1 - 0.4 * c.policy); return -(direct + wealth); },
      format: (v) => (v > -0.005 ? "0.00" : v.toFixed(2)) + " pp", severity: (v) => Math.min(1, -v / 2.5),
      sub: () => "from 3.4% Q3 2026 growth", how: "Direct: cut × the average of the St. Louis Fed (0.97pp) and PIMCO net-of-imports (0.4pp) estimates of AI's growth contribution. Plus wealth effect: stock value lost × 3¢ per $1 ÷ US GDP ($" + (gdp.value / 1000).toFixed(1) + "tn), reduced by the policy-response assumption.", src: [s.stl, s.pimco, s.fredGDP, s.bea] },
    { label: "US tech jobs at risk (dot-com scale)", tag: "model", fn: (c) => c.h("jobs") * c.b("dotcomITJobs"), format: (v) => Math.round(v / 1000) + "k", severity: (v, c) => c.h("jobs"),
      sub: () => "2001–04 lost 245k computer-design jobs", how: "Jobs-node stress × the 245,000 US computer-systems-design jobs lost from March 2001 to 2004. A stress of 100 means a dot-com-sized hit. 2026 already has 134,917 tech layoffs before any bust.", src: [s.itJobs, s.layoffs] },
    { label: "India tech exports at risk", tag: "model", fn: (c) => c.h("indiait") * c.b("indiaExports") * c.b("indiaDiscretionary") / 0.6, format: money, severity: (v, c) => c.h("indiait"),
      sub: () => "of $246bn FY26 exports", how: "Indian-IT stress × FY26 exports ($246bn) × 20% discretionary share (assumption) ÷ 0.6 (stress of 60 = all discretionary work lost).", src: [s.nasscom] },
  ];

